contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0));
        require(recipient != address(this));

        uint256 senderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientBefore = c.balanceOf(recipient); if (__ESBMC_reverted()) return;

        bool reverted;
        bool success = c.transfer(recipient, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            require(success);
        }

        uint256 senderAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientAfter = c.balanceOf(recipient); if (__ESBMC_reverted()) return;

        assert(reverted || (senderAfter + recipientAfter == senderBefore + recipientBefore));
    }
}

